from typing import List, Tuple

def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, +, -, *, / and parentheses.
    Supports normal operator precedence. Division is integer division truncating toward zero.
    Spaces may appear anywhere.
    """

    # Tokenize the expression
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue
        if expr[i] in '+-*/()':
            tokens.append(expr[i])
            i += 1
        else:
            # Parse number
            num_str = ''
            while i < len(expr) and expr[i].isdigit():
                num_str += expr[i]
                i += 1
            tokens.append(int(num_str))

    # Two-stack approach for evaluation
    # ops stack stores operators
    # vals stack stores values (integers)
    ops = []
    vals = []

    def peek_op():
        if not ops:
            return '+'
        return ops[-1]

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_op():
        op = ops.pop()
        a = vals.pop()
        b = vals.pop()

        if op == '+':
            vals.append(b + a)
        elif op == '-':
            vals.append(b - a)
        elif op == '*':
            vals.append(b * a)
        elif op == '/':
            # Integer division truncating toward zero
            # Python's // operator floors for negative numbers, so we need manual handling
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            result = int(b / a)
            vals.append(result)

    # Process tokens
    for token in tokens:
        if isinstance(token, int):
            vals.append(token)
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                apply_op()
            ops.pop() # Remove '('
        else:
            # Operator
            while ops and precedence(ops[-1]) >= precedence(token):
                apply_op()
            ops.append(token)

    # Apply remaining operators
    while ops:
        apply_op()

    return vals[0] if vals else 0
