from typing import List, Tuple

def calc(expr: str) -> int:
    """
    Evaluate an integer expression with +, -, *, /, ^, unary minus and parentheses.
    Spaces may appear anywhere.
    Precedence: 
      1. ^ (exponent, right-associative)
      2. unary minus
      3. * and / (left-associative)
      4. + and - (left-associative)
    Division truncates toward zero. Exponents are never negative.
    """

    # Tokenize the expression
    tokens = []
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit() or (c == '-' and i + 1 < len(expr) and expr[i+1].isdigit()):
            # Handle multi-digit numbers
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '-'):
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/^':
            tokens.append((c,))
            i += 1
        elif c == '(':
            tokens.append(('LPAREN',))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN',))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")

    # Shunting-yard algorithm to convert infix to postfix (RPN)
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    right_assoc = {'^': True}

    output_queue = []
    op_stack = []

    def apply_op(op):
        if not op_stack:
            return
        while op_stack and precedence[op_stack[-1]] >= precedence[op]:
            if op == '^' and right_assoc.get(op_stack[-1], False):
                # Right-associative check for exponent
                pass 
            else:
                break
        if not op_stack:
            return
        top_op = op_stack.pop()
        left_val = output_queue.pop()
        right_val = output_queue.pop()

        if top_op == '+':
            result = left_val + right_val
        elif top_op == '-':
            result = left_val - right_val
        elif top_op == '*':
            result = left_val * right_val
        elif top_op == '/':
            # Integer division truncating toward zero
            if right_val == 0:
                raise ZeroDivisionError("Division by zero")
            result = int(left_val / right_val)
        elif top_op == '^':
            result = left_val ** right_val
        output_queue.append(result)

    for token in tokens:
        if token[0] == 'NUM':
            output_queue.append(token[1])
        elif token[0] == 'LPAREN':
            op_stack.append(token[0])
        elif token[0] == 'RPAREN':
            while op_stack and op_stack[-1] != 'LPAREN':
                apply_op(op_stack.pop())
            op_stack.pop() # Pop LPAREN
        elif token[0] in '+-*/^':
            while (op_stack and op_stack[-1] not in ('LPAREN', '-')) or \
                   (precedence[token[0]] <= precedence[op_stack[-1]]):
                apply_op(op_stack.pop())
            op_stack.append(token[0])

    while op_stack:
        if op_stack[-1] == 'LPAREN':
            raise ValueError("Mismatched parentheses")
        apply_op(op_stack.pop())

    if len(output_queue) != 1:
        raise ValueError("Invalid expression")

    return output_queue[0]
