def spiral_order(m: list[list[int]]) -> list[int]:
    if not m or not m[0]:
        return []

    rows, cols = len(m), len(m[0])
    result = []
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1

    while top <= bottom and left <= right:
        # Traverse from left to right along the top row
        for col in range(left, right + 1):
            result.append(m[top][col])
        top += 1

        # Traverse from top to bottom along the right column
        for row in range(top, bottom + 1):
            result.append(m[row][right])
        right -= 1

        # Check if we still need to traverse the bottom row
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(m[bottom][col])
            bottom -= 1

        # Check if we still need to traverse the left column
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(m[row][left])
            left += 1

    return result
