    # Step 1: Tokenize and handle unary minus
    # We'll replace sequences like "-2" (unary) with a marker, but since Python's eval doesn't support ^ or custom precedence easily,
    # we need to implement the logic manually.

    # Strategy: 
    # 1. Replace unary minus with a specific token or handle during parsing.
    # 2. Implement a recursive descent parser respecting precedence:
    #    - UnaryMinus -> (UnaryMinus | Number)
    #    - Power   -> UnaryMinus | (Power | Power ^ Power) [Right Assoc]
    #    - MultDiv -> Power | (MultDiv * MultDiv) | (MultDiv / MultDiv) [Left Assoc]
    #    - AddSub  -> MultDiv | (AddSub + AddSub) | (AddSub - AddSub) [Left Assoc]

    # To simplify, we can use a stack-based approach with two stacks: values and operators.
    # However, handling unary minus and right-associative exponentiation requires care.

    # Let's implement a recursive descent parser.

    def parse():
        return parse_add_sub()

    def parse_add_sub():
        left = parse_mult_div()
        while True:
            if expr[0] in ('+', '-'):
                op = expr[0]
                expr = expr[1:]
                right = parse_mult_div()
                if op == '+':
                    left += right
                else:
                    left -= right
            else:
                break
        return left

    def parse_mult_div():
        left = parse_power()
        while True:
            if expr[0] in ('*', '/'):
                op = expr[0]
                expr = expr[1:]
                right = parse_power()
                if op == '*':
                    left *= right
                else:
                    # Integer division truncating toward zero
                    left = int(left / right)
            else:
                break
        return left

    def parse_power():
        left = parse_unary_minus()
        while True:
            if expr[0] == '^':
                expr = expr[1:]
                right = parse_power() # Right associative
                left = left ** right
            else:
                break
        return left

    def parse_unary_minus():
        if expr[0] == '-':
            expr = expr[1:]
            return -parse_unary_minus()
        else:
            return parse_number()

    def parse_number():
        # Find the end of the number
        start = 0
        while start < len(expr) and expr[start].isdigit():
            start += 1
        num_str = expr[start]
        if not num_str:
            return 0
        return int(num_str)

    # Initial call
