def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", 
            "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", 
            "seventeen", "eighteen", "nineteen"]

    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    hundreds = ["", "hundred", "thousand", "million", "billion"]

    def less_than_thousand(num):
        if num == 0:
            return ""
        result = []
        if num >= 100:
            result.append(ones[num // 100] + "hundred")
            num %= 100
        if num >= 20:
            result.append(tens[num // 10] + "-" + ones[num % 10])
        elif num > 0:
            result.append(ones[num])
        return " ".join(result)

    def less_than_million(num):
        if num == 0:
            return ""
        result = []
        for i in range(3, -1, -1):
            group = num // (100 ** i)
            if group > 0:
                result.append(hundreds[i] + " " + less_than_thousand(group % 1000))
            num %= (100 ** i)
        return " ".join(result)

    return less_than_million(n)
