def evaluate(expr: str) -> int:
    import re

    # Remove all spaces
    expr = expr.replace(" ", "")

    # Tokenize the expression into numbers and operators/parentheses
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isdigit():
            num = ""
            while i < len(expr) and expr[i].isdigit():
                num += expr[i]
                i += 1
            tokens.append(int(num))
        elif expr[i] in "+-*/()":
            tokens.append(expr[i])
            i += 1
        else:
            raise ValueError(f"Invalid character: {expr[i]}")

    # Two stacks approach: one for values, one for operators
    values = []
    ops = []

    def apply_op():
        if not ops:
            return
        op = ops.pop()
        b = values.pop()
        a = values.pop()
        if op == '+':
            values.append(a + b)
        elif op == '-':
            values.append(a - b)
        elif op == '*':
            values.append(a * b)
        elif op == '/':
            # Integer division truncating toward zero
            values.append(int(a / b))

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    for token in tokens:
        if isinstance(token, int):
            values.append(token)
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                apply_op()
            if ops:
                ops.pop()  # Remove '('
        else:
            # It's an operator
            while (ops and ops[-1] != '(' and 
                   precedence(ops[-1]) >= precedence(token)):
                apply_op()
            ops.append(token)

    while ops:
        apply_op()

    return values[0] if values else 0
