def int_to_words(n: int) -> str:
    """Convert an integer to its English word representation."""

    # Define word lists for each magnitude
    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    # Scale words
    thousands = ["", "thousand", "million"]

    def convert_less_than_1000(num):
        if num == 0:
            return ""

        result = []

        # Hundreds place
        if num >= 100:
            result.append(ones[num // 100])
            result.append("hundred")
            num %= 100

        # Tens and ones place
        if num >= 20:
            result.append(tens[num // 10])
            if num % 10 != 0:
                result.append(ones[num % 10])
        elif num > 0:
            result.append(teens[num - 10])

        return " ".join(result)

    def convert_less_than_1000000(num):
        if num == 0:
            return ""

        parts = []

        # Millions
        if num >= 1000000:
            parts.append(convert_less_than_1000(num // 1000000))
            num %= 1000000

        # Thousands
        if num >= 1000:
            parts.append(convert_less_than_1000(num // 1000))
            parts.append("thousand")
            num %= 1000

        # Rest
        if num > 0:
            parts.append(convert_less_than_1000(num))

        return " ".join(parts)

    if n == 0:
        return "zero"

    result = convert_less_than_1000000(n)
    return result
