def evaluate(expr: str) -> int:
    """
    Evaluates an arithmetic expression containing non-negative integers, +, -, *, / and parentheses,
    with normal operator precedence. Spaces may appear anywhere. Division is integer division
    that truncates toward zero.
    """
    def apply_op(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            # Integer division truncating toward zero
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            return int(a / b)
        return 0

    def precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    def process_expression(tokens):
        values = []
        ops = []

        def process_tokens():
            while tokens:
                token = tokens.pop(0)
                if isinstance(token, int):
                    values.append(token)
                elif token in ('+', '-', '*', '/'):
                    op = token
                    while (ops and precedence(ops[-1]) >= precedence(op)):
                        op2 = ops.pop()
                        if len(values) < 2:
                            raise ValueError("Invalid expression structure")
                        val2 = values.pop()
                        val1 = values.pop()
                        values.append(apply_op(op2, val2, val1))
                    ops.append(op)
                elif token == '(':
                    ops.append(token)
                elif token == ')':
                    while ops and ops[-1] != '(':
                        op = ops.pop()
                        if len(values) < 2:
                            raise ValueError("Invalid expression structure")
                        val2 = values.pop()
                        val1 = values.pop()
                        values.append(apply_op(op, val2, val1))
                    if ops and ops[-1] == '(':
                        ops.pop()  # Pop '('
                    else:
                        raise ValueError("Mismatched parentheses")
                else:
                    raise ValueError(f"Unknown token: {token}")

            while ops:
                op = ops.pop()
