import re

def calc(expr: str) -> int:
    """
    Evaluates an integer expression with +, -, *, /, ^, unary minus and parentheses.
    """

    def tokenize(s: str) -> list:
        s = s.replace(' ', '')
        tokens = []
        i = 0
        while i < len(s):
            char = s[i]
            if char.isdigit() or char == '.':
                j = i
                while j < len(s) and (s[j].isdigit() or s[j] == '.'):
                    j += 1
                num_str = s[i:j]
                tokens.append(float(num_str))
                i = j
                continue
            elif char in '+-*/^()':
                tokens.append(char)
                i += 1
                continue
            elif char == '-':
                # Check for unary minus
                is_unary = False
                if not tokens:
                    is_unary = True
                else:
                    last_token = tokens[-1]
                    if isinstance(last_token, float) or last_token in '([':
                        is_unary = True

                if is_unary:
                    # Treat as a special unary minus token
                    tokens.append('UNARY_MINUS')
                else:
                    tokens.append('-')
                i += 1
                continue
            else:
                raise ValueError(f"Invalid character in expression: {char}")
        return tokens

    def apply_op(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            # Integer division truncating toward zero
            return int(a / b)
        elif op == '^':
            # Exponents are never negative
            if b < 0:
                raise ValueError("Negative exponent")
            return int(a ** b)
        elif op == 'UNARY_MINUS':
            return -a
        raise ValueError(f"Unknown operator: {op}")

    def precedence(op):
        if op in ['+', '-']:
            return 1
        if op in ['*', '/']:
            return 2
        if op == '^':
            return 3
        return 0

    def process_tokens(tokens):
        values = []
        ops = []

        def process_op_on_stack():
            op = ops.pop()
            if op == 'UNARY_MINUS':
                val = values.pop()
                values.append(apply_op(op, val, None))
            else:
                val2 = values.pop()
                val1 = values.pop()
                values.append(apply_op(op, val2, val1))

        for token in tokens:
            if isinstance(token, float):
                values.append(token)
            elif token == '(':
                ops.append(token)
            elif token == ')':
                while ops and ops[-1] != '(':
                    process_op_on_stack()
                if not ops or ops[-1] != '(':
                    raise ValueError("Mismatched parentheses")
                ops.pop()  # Pop '('
            elif token in ['+', '-', '*', '/', '^', 'UNARY_MINUS']:
                op = token
                # Handle right-associativity for '^'
                while (ops and ops[-1] != '(' and
                       (precedence(ops[-1]) > precedence(op) or
                        (precedence(ops[-1]) == precedence(op) and op != '^'))):
                    process_op_on_stack()
                ops.append(op)
            else:
                raise ValueError(f"Unexpected token: {token}")

        while ops:
            if ops[-1] == '(':
                raise ValueError("Mismatched parentheses")
            process_op_on_stack()

        if len(values) != 1 or ops:
            raise ValueError("Invalid expression structure")

        return int(values[0])

    tokens = tokenize(expr)
    return process_tokens(tokens)
