                # Handle hyphenation for 21-99 not multiples of ten
                if t > 1 and u > 0:
                    # The structure above already handles the words, we just need to join them correctly
                    pass
                elif t > 1 and u == 0:
                    # This case (e.g., 20, 30) is handled by tens[t] and doesn't need a unit word
                    pass

        return " ".join(words)

    def convert_chunk(n_chunk):
        if n_chunk == 0:
            return ""

        words_list = []

        # Process hundreds, tens, units
        h = n_chunk // 100
        rem = n_chunk % 100

        if h > 0:
            words_list.append(units[h] + "hundred")

        if rem > 0:
            if rem < 10:
                words_list.append(units[rem])
            elif rem >= 10 and rem <= 19:
                words_list.append(teens[rem])
            else:
                t = rem // 10
                u = rem % 10

                t_word = tens[t]
                u_word = units[u]

                if u > 0:
                    # If there's a unit digit, we need to join the tens word and the unit word with a hyphen
                    words_list.append(f"{t_word}-{u_word}")
                else:
                    # If u is 0 (e.g., 20, 30), just use the tens word
                    words_list.append(t_word)

        return " ".join(words_list)


    millions = n // 1000000
    remainder = n % 1000000

    result_parts = []

    # Millions part
    if millions > 0:
        millions_words = convert_chunk(millions)
        result_parts.append(millions_words + "million")

    # Thousands part
    thousands_chunk = remainder // 1000
    remainder %= 1000

    if thousands_chunk > 0:
        thousands_words = convert_chunk(thousands_chunk)
        result_parts.append(thousands_words + "thousand")

    # Hundreds/Tens/Units part
    units_chunk = remainder
    if units_chunk > 0:
        units_words = convert_chunk(units_chunk)
        result_parts.append(units_words)

    return " ".join(result_parts)
