from typing import Any, Dict, List, Union

def flatten_json(obj: Dict) -> Dict:
    """
    Flattens nested dicts and lists into one dict whose keys are paths joined with '.'.
    List items use their index as the path part. A nested empty dict or empty list 
    is kept as the value at its path. Other values (numbers, strings, booleans, None) 
    are leaves.
    """
    result = {}

    def _flatten(current_obj: Any, path: str = ""):
        if isinstance(current_obj, dict):
            for key, value in current_obj.items():
                new_path = f"{path}.{key}" if path else key
                _flatten(value, new_path)
        elif isinstance(current_obj, list):
            for index, item in enumerate(current_obj):
                new_path = f"{path}.{index}" if path else str(index)
                _flatten(item, new_path)
        else:
            # Leaf node (str, int, float, bool, None)
            result[path] = current_obj

    # Handle the initial call for the top-level dictionary structure
    # We need a slight modification to handle the specific requirement:
    # "A nested empty dict or empty list is kept as the value at its path."
    # The standard recursion above handles this implicitly if we treat empty containers
    # as containers that are processed, but we need to ensure the path is recorded
    # even if the content is empty.

    def _flatten_with_empty_check(current_obj: Any, path: str = ""):
        if isinstance(current_obj, dict):
            if not current_obj:
                result[path] = {}
                return
            for key, value in current_obj.items():
                new_path = f"{path}.{key}" if path else key
                _flatten_with_empty_check(value, new_path)
        elif isinstance(current_obj, list):
            if not current_obj:
                result[path] = []
                return
            for index, item in enumerate(current_obj):
                new_path = f"{path}.{index}" if path else str(index)
                _flatten_with_empty_check(item, new_path)
        else:
            # Leaf node
            result[path] = current_obj

    _flatten_with_empty_check(obj)
    return result
