            if not current_obj:
                # Keep empty dict as value
                if parent_key:
                    result[parent_key] = {}
                return

            for key, value in current_obj.items():
                new_key = f"{parent_key}.{key}" if parent_key else key
                _flatten(value, new_key)

        elif isinstance(current_obj, list):
            if not current_obj:
                # Keep empty list as value
                if parent_key:
                    result[parent_key] = []
                return

            for index, item in enumerate(current_obj):
                new_key = f"{parent_key}.{index}" if parent_key else str(index)
                _flatten(item, new_key)

        else:
            # Leaf node (number, string, boolean, None)
            if parent_key:
                result[parent_key] = current_obj

    _flatten(obj)
    return result
