def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    def helper(num: int) -> str:
        if num == 0:
            return ""
        elif num < 10:
            return ones[num]
        elif num < 20:
            return teens[num - 10]
        elif num < 100:
            if num % 10 == 0:
                return tens[num // 10]
            else:
                return f"{tens[num // 10]}-{ones[num % 10]}"
        else:
            # This handles the hundreds place
            return f"{ones[num // 100]} hundred"

    parts = []
    # Million
    million = n // 1000000
    if million > 0:
        m_val = million % 1000
        if m_val == 0:
            parts.append(f"{ones[million]} million")
        else:
            parts.append(f"{helper(m_val)} million")

    # Thousand
    thousand = (n % 1000000) // 1000
    if thousand > 0:
        t_val = thousand % 1000
        if t_val == 0:
            parts.append(f"{ones[thousand]} thousand")
        else:
            parts.append(f"{helper(t_val)} thousand")

    # Hundreds/Tens/Ones
    remainder = n % 1000
    if remainder > 0:
        parts.append(helper(remainder))

    return " ".join(parts)
