def flatten_json(obj: dict) -> dict:
    """
    Flattens nested dictionaries and lists into a single dictionary where keys 
    are dot-separated paths. List items use their index as the path part.
    Nested empty dicts or lists are preserved as values.
    """
    result = {}

    def _flatten(current_obj, path=""):
        if isinstance(current_obj, dict):
            if not current_obj:
                result[path] = {}
                return
            for key, value in current_obj.items():
                new_path = f"{path}.{key}" if path else key
                _flatten(value, new_path)
        elif isinstance(current_obj, list):
            if not current_obj:
                result[path] = []
                return
            for index, value in enumerate(current_obj):
                new_path = f"{path}.{index}"
                _flatten(value, new_path)
        else:
            result[path] = current_obj

    _flatten(obj)
    return result
