def calc(expr: str) -> int:
    import re

    # Tokenize the expression
    tokens = []
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append(('OP', c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")

    # Add end marker
    tokens.append(('END', None))

    pos = 0

    def peek():
        return tokens[pos]

    def consume():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_expr():
        # Handles + and - (left-associative)
        left = parse_term()
        while peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = consume()[1]
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        # Handles * and / (left-associative)
        left = parse_unary()
        while peek()[0] == 'OP' and peek()[1] in ('*', '/'):
            op = consume()[1]
            right = parse_unary()
            if op == '*':
                left = left * right
            else:
                # Integer division truncating toward zero
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                # Python's // truncates toward negative infinity, so we need to handle truncation toward zero
                result = left / right
                left = int(result) if result >= 0 else -int(-result)
        return left

    def parse_unary():
        # Handles unary minus
        if peek()[0] == 'OP' and peek()[1] == '-':
            consume()
            return -parse_unary()
        if peek()[0] == 'OP' and peek()[1] == '+':
            consume()
            return parse_unary()
        return parse_power()

    def parse_power():
        # Handles ^ (right-associative)
        base = parse_primary()
        if peek()[0] == 'OP' and peek()[1] == '^':
            consume()
            exponent = parse_unary()  # Right-associative: parse unary which can handle further ^
            return int(base ** exponent)
        return base

    def parse_primary():
        # Handles numbers and parenthesized expressions
        t = peek()
        if t[0] == 'NUM':
            consume()
            return t[1]
        if t[0] == 'OP' and t[1] == '(':
            consume()
            val = parse_expr()
            if peek()[0] != 'OP' or peek()[1] != ')':
                raise ValueError("Expected closing parenthesis")
            consume()
            return val
        raise ValueError(f"Unexpected token: {t}")

    result = parse_expr()
    if peek()[0] != 'END':
        raise ValueError("Unexpected token after expression")
    return result
