    def dp(i):
        if i == len(s):
            return 1
        if i in memo:
            return memo[i]

        # Case 1: Single digit decoding
        digit = int(s[i])
        if digit >= 1 and digit <= 9:
            result = dp(i + 1)
        else:
            result = 0

        # Case 2: Two-digit decoding
        if i + 1 < len(s):
            two_digit = int(s[i:i+2])
            if two_digit >= 10 and two_digit <= 26:
                ways_two = dp(i + 2)
                result += ways_two

        memo[i] = result
        return result

    return dp(0)
