def flatten_json(obj: dict) -> dict:
    """
    Flattens nested dictionaries and lists into a single dictionary.
Keys are formed by joining path segments with '.'. List items use their index as the path part.
Nested empty dicts or empty lists are kept as the value at their path.
Other values are leaves.
"""
    result = {}

    def recurse(data, path):
        if isinstance(data, dict):
            for key, value in data.items():
                new_path = f"{path}.{key}"
                recurse(value, new_path)
        elif isinstance(data, list):
            for index, item in enumerate(data):
                new_path = f"{path}.{index}"
                recurse(item, new_path)
        else:
            # Base case: leaf node
            result[path] = data

    recurse(obj, "")
    return result
