from collections import deque

def count_islands(grid: list[str]) -> int:
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1' and not visited[r][c]:
                count += 1
                # BFS to mark the whole island as visited
                q = deque()
                q.append((r, c))
                visited[r][c] = True

                while q:
                    cr, cc = q.popleft()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == '1' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))

    return count
