        remainder = num % 100
        if hundreds > 0:
            parts.append(f"{ones[hundreds]} hundred")
        if remainder > 0:
            if remainder < 10:
                parts.append(ones[remainder])
            elif remainder < 20:
                parts.append(teens[remainder - 10])
            else:
                t = remainder // 10
                o = remainder % 10
                if o == 0:
                    parts.append(tens[t])
                else:
                    parts.append(f"{tens[t]}-{ones[o]}")
        return " ".join(parts)

    million = n // 1_000_000
    thousand = (n % 1_000_000) // 1_000
    remainder = n % 1_000

    words = []
    if million > 0:
        words.append(f"{convert_chunk(million)} million")
    if thousand > 0:
        words.append(f"{convert_chunk(thousand)} thousand")
    if remainder > 0:
        words.append(convert_chunk(remainder))

    return " ".join(words)
