import re

def calc(expr: str) -> int:
    # Tokenize the expression
    tokens = re.findall(r'\d+|[+\-*/^()]', expr)

    def get_precedence(op, is_unary=False):
        if is_unary:
            return 3
        if op == '^':
            return 4
        if op in ('*', '/'):
            return 2
        if op in ('+', '-'):
            return 1
        return 0

    def apply_op(ops, values):
        op = ops.pop()
        if op == 'u-':
            val = values.pop()
            values.append(-val)
        else:
            right = values.pop()
            left = values.pop()
            if op == '+': values.append(left + right)
            elif op == '-': values.append(left - right)
            elif op == '*': values.append(left * right)
            elif op == '/':
                # Integer division truncating toward zero
                if left * right < 0 and left % right != 0:
                    values.append(left // right + 1)
                else:
                    values.append(left // right)
            elif op == '^':
                values.append(left ** right)

    values = []
    ops = []
    i = 0
    while i < len(tokens):
        token = tokens[i]

        if token.isdigit():
            values.append(int(token))
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                apply_op(ops, values)
            ops.pop() # remove '('
        else:
            # Check if '-' is unary
            # It's unary if it's at the start or follows an operator or '('
            is_unary = False
            if token == '-':
                if i == 0 or tokens[i-1] in '+-*/^(':
                    is_unary = True

            if is_unary:
                # Unary minus has higher precedence than binary *, /, +, -
                # but lower than exponentiation (based on -2^2 = -4)
                # However, the prompt says: ^, then unary minus, then *, /, then +, -
                # This means -2^2 is -(2^2) = -4.
                # To achieve this, we treat unary minus as a high precedence operator
                # but we must handle the right-associativity of ^ carefully.

                # We push unary minus as a special token
                while ops and ops[-1] != '(' and get_precedence(ops[-1], ops[-1] == 'u-') > 3:
                    apply_op(ops, values)
                ops.append('u-')
            else:
                # Binary operators
                prec = get_precedence(token)
                while ops and ops[-1] != '(' :
                    top_op = ops[-1]
                    top_prec = get_precedence(top_op, top_op == 'u-')

                    # Exponentiation is right-associative
                    if token == '^':
                        if top_prec > prec:
                            apply_op(ops, values)
                        else:
                            break
                    else:
                        # Other operators are left-associative
                        if top_prec >= prec:
                            apply_op(ops, values)
                        else:
                            break
                ops.append(token)
        i += 1

    while ops:
        apply_op(ops, values)

    return values[0]
