        elif isinstance(current_obj, list) and current_obj:
            for index, value in enumerate(current_obj):
                new_path = f"{path}.{index}" if path else str(index)
                yield from recurse(value, new_path)
        # Otherwise, it's a leaf (including empty dicts/lists)
        else:
            yield path, current_obj

    # The root is a dict, so we start recursion on its values
    # to ensure the top-level keys are handled correctly.
    result = {}
    for key, value in obj.items():
        for p, v in recurse(value, str(key)):
            result[p] = v

    # Special case: if the input dict is empty, return empty dict
    # If the input dict has keys but they all lead to empty structures, 
    # the loop above handles it.
    return result
