        if s[i - 1] != '0':
            dp[i] += dp[i - 1]

        if i >= 2 and s[i - 2] != '0':
            two_digit = int(s[i - 2:i])
            if 10 <= two_digit <= 26:
                dp[i] += dp[i - 2]

