def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    ones = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
            "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
            "seventeen", "eighteen", "nineteen"]
    tens = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy",
            "eighty", "ninety"]

    def convert_below_hundred(num: int) -> str:
        if num < 20:
            return ones[num]
        return tens[num // 10] + ("-" + ones[num % 10] if num % 10 else "")

    def convert_below_thousand(num: int) -> str:
        if num == 0:
            return ""
        parts = []
        if num >= 100:
            parts.append(ones[num // 100] + " hundred")
            num %= 100
        if num > 0:
            parts.append(convert_below_hundred(num))
        return " ".join(parts)

    def convert_below_million(num: int) -> str:
        if num == 0:
            return ""
        parts = []
        if num >= 1000:
            parts.append(convert_below_thousand(num // 1000) + " thousand")
            num %= 1000
        if num > 0:
            parts.append(convert_below_thousand(num))
        return " ".join(parts)

    def convert_below_billion(num: int) -> str:
        if num == 0:
            return ""
        parts = []
        if num >= 1000000:
            parts.append(convert_below_thousand(num // 1000000) + " million")
            num %= 1000000
        if num > 0:
            parts.append(convert_below_million(num))
        return " ".join(parts)

    return convert_below_billion(n)
