def flatten_json(obj: dict) -> dict:
    """
    Flatten a nested dictionary into a single-level dictionary.

    Keys are paths joined with '.'. List items use their index as the path part.
    Empty dicts/lists are kept as values at their path.
    """
    result = {}

    def _flatten(current, prefix):
        if isinstance(current, dict):
            if not current:
                result[prefix] = current
            else:
                for key, value in current.items():
                    new_prefix = f"{prefix}.{key}" if prefix else str(key)
                    _flatten(value, new_prefix)
        elif isinstance(current, list):
            if not current:
                result[prefix] = current
            else:
                for index, item in enumerate(current):
                    new_prefix = f"{prefix}.{index}" if prefix else str(index)
                    _flatten(item, new_prefix)
        else:
            result[prefix] = current

    _flatten(obj, "")
    return result
