def evaluate(expr: str) -> int:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif c in '+-*/()':
            tokens.append(c)
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    # Recursive descent parser
    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def consume():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def parse_expression():
        # expression = term (('+' | '-') term)*
        result = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        # term = factor (('*' | '/') factor)*
        result = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                result *= right
            else:
                # Integer division truncating toward zero
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                # Python's // truncates toward negative infinity, so we need to handle truncation toward zero
                if (result >= 0 and right > 0) or (result < 0 and right < 0):
                    result = result // right
                else:
                    result = -((-result) // right)
        return result

    def parse_factor():
        # factor = '(' expression ')' | number
        if peek() == '(':
            consume()  # consume '('
            result = parse_expression()
            if peek() != ')':
                raise ValueError("Expected ')'")
            consume()  # consume ')'
            return result
        else:
            tok = consume()
            if not isinstance(tok, int):
                raise ValueError(f"Expected number, got {tok}")
            return tok

    result = parse_expression()
    if pos[0] != len(tokens):
        raise ValueError("Unexpected tokens remaining")
    return result
