def calc(expr: str) -> int:
    import re

    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+' | '-') term)*
        left = parse_term()
        while peek() and peek()[0] in ('+', '-'):
            op = consume()[0]
            right = parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left

    def parse_term():
        # term := unary (('*' | '/') unary)*
        left = parse_unary()
        while peek() and peek()[0] in ('*', '/'):
            op = consume()[0]
            right = parse_unary()
            if op == '*':
                left = left * right
            else:
                # Integer division truncating toward zero
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                q = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    q = -q
                left = q
        return left

    def parse_unary():
        # unary := ('-' | '+') unary | power
        if peek() and peek()[0] in ('+', '-'):
            op = consume()[0]
            val = parse_unary()
            if op == '-':
                return -val
            else:
                return val
        return parse_power()

    def parse_power():
        # power := base ('^' power)?  (right-associative)
        base = parse_base()
        if peek() and peek()[0] == '^':
            consume()
            exp = parse_power()
            return int(base ** exp)
        return base

    def parse_base():
        # base := NUM | '(' expr ')'
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'NUM':
            consume()
            return tok[1]
        if tok[0] == '(':
            consume()
            val = parse_expr()
            if not peek() or peek()[0] != ')':
                raise ValueError("Expected closing parenthesis")
            consume()
            return val
        raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected tokens remaining")
    return result
