    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]

    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    def two_digits(num: int) -> str:
        if num < 20:
            return ones[num]
        else:
            t = num // 10
            o = num % 10
            if o == 0:
                return tens[t]
            else:
                return tens[t] + "-" + ones[o]

    def three_digits(num: int) -> str:
        if num == 0:
            return ""
        parts = []
        if num >= 100:
            parts.append(ones[num // 100] + " hundred")
            num %= 100
        if num > 0:
            parts.append(two_digits(num))
        return " ".join(parts)

    result_parts = []

    # Million
    if n >= 1_000_000:
        millions = n // 1_000_000
        result_parts.append(three_digits(millions) + " million")
        n %= 1_000_000

    # Thousand
    if n >= 1_000:
        thousands = n // 1_000
        result_parts.append(three_digits(thousands) + " thousand")
        n %= 1_000

    # Remaining
    if n > 0:
        result_parts.append(three_digits(n))

    return " ".join(result_parts)
