def calc(expr: str) -> int:
    # Remove all spaces
    expr = expr.replace(' ', '')

    pos = [0]  # Use a list to allow modification in nested functions

    def peek():
        if pos[0] < len(expr):
            return expr[pos[0]]
        return None

    def consume():
        ch = expr[pos[0]]
        pos[0] += 1
        return ch

    def parse_expr():
        # expr := term (('+' | '-') term)*
        result = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                result += right
            else:
                result -= right
        return result

    def parse_term():
        # term := unary (('*' | '/') unary)*
        result = parse_unary()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_unary()
            if op == '*':
                result *= right
            else:
                # Integer division truncating toward zero
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                # Python's // truncates toward negative infinity, so we need to adjust
                q = abs(result) // abs(right)
                if (result < 0) != (right < 0):
                    q = -q
                result = q
        return result

    def parse_unary():
        # unary := '-' unary | power
        if peek() == '-':
            consume()
            return -parse_unary()
        return parse_power()

    def parse_power():
        # power := base ('^' power)?  (right-associative)
        base = parse_base()
        if peek() == '^':
            consume()
            exponent = parse_power()  # Right-associative: parse the rest as power
            return int(base ** exponent)
        return base

    def parse_base():
        # base := number | '(' expr ')'
        if peek() == '(':
            consume()
            result = parse_expr()
            if peek() != ')':
                raise ValueError("Expected closing parenthesis")
            consume()
            return result
        # Parse number
        start = pos[0]
        while pos[0] < len(expr) and expr[pos[0]].isdigit():
            pos[0] += 1
        if pos[0] == start:
            raise ValueError("Expected number")
        return int(expr[start:pos[0]])

    result = parse_expr()
    if pos[0] != len(expr):
        raise ValueError("Unexpected character at position " + str(pos[0]))
    return result
