import re


def glob_match(name: str, pattern: str) -> bool:
    """Match the whole name against a shell-style pattern, case-sensitively."""
    # Convert the glob pattern to a regular expression
    i = 0
    n = len(pattern)
    regex_parts = []

    while i < n:
        c = pattern[i]
        if c == '*':
            regex_parts.append('.*')
            i += 1
        elif c == '?':
            regex_parts.append('.')
            i += 1
        elif c == '[':
            # Find the closing bracket
            j = i + 1
            negated = False
            if j < n and pattern[j] == '!':
                negated = True
                j += 1
            # Collect characters until closing ']'
            chars = []
            while j < n and pattern[j] != ']':
                # Check for range like a-z
                if (j + 2 < n and pattern[j + 1] == '-' and pattern[j + 2] != ']'):
                    start = pattern[j]
                    end = pattern[j + 2]
                    # Add all characters in the range
                    for code in range(ord(start), ord(end) + 1):
                        chars.append(chr(code))
                    j += 3
                else:
                    chars.append(pattern[j])
                    j += 1
            # j should now point to ']'
            if j < n and pattern[j] == ']':
                j += 1
            # Build the character class
            if negated:
                # For negated, we need to match any character NOT in the set
                # But we need to be careful with special characters in regex
                # Escape any characters that are special in regex character classes
                escaped_chars = []
                for ch in chars:
                    if ch in r'\^$':
                        escaped_chars.append('\\' + ch)
                    else:
                        escaped_chars.append(ch)
                regex_parts.append('[^' + ''.join(escaped_chars) + ']')
            else:
                escaped_chars = []
                for ch in chars:
                    if ch in r'\^$':
                        escaped_chars.append('\\' + ch)
                    else:
                        escaped_chars.append(ch)
                regex_parts.append('[' + ''.join(escaped_chars) + ']')
            i = j
        else:
            # Escape regex special characters
            if c in r'.^$+{}()|[]\\':
                regex_parts.append('\\' + c)
            else:
                regex_parts.append(c)
            i += 1

    regex = ''.join(regex_parts)
    return re.fullmatch(regex, name) is not None
