import ast
import operator

def evaluate(expr: str) -> int:
    class Evaluator(ast.NodeVisitor):
        def __init__(self):
            self.operators = {
                ast.Add: operator.add,
                ast.Sub: operator.sub,
                ast.Mult: operator.mul,
                ast.Div: operator.floordiv
            }
            self.stack = []
            self.current = 0

        def visit_Num(self, node):
            self.stack.append(node.n)
            self.generic_visit(node)

        def visit_BinOp(self, node):
            right = self.visit(node.right)
            left = self.visit(node.left)
            op_type = type(node.op)
            if op_type in self.operators:
                func = self.operators[op_type]
                # Handle division truncating toward zero
                if op_type is ast.Div:
                    result = func(left, right)
                    if left * right < 0 and result < 0:
                        result = -(-result)
                    elif left * right > 0 and result != int(result):
                        # For positive, normal floor division
                        result = int(func(left, right))
                    self.current = result
                else:
                    self.current = func(left, right)
            else:
                raise ValueError("Unsupported operator")
            self.generic_visit(node)

        def visit_Expr(self, node):
            self.current = self.visit(node.value)
            self.generic_visit(node)

        def visit_Paren(self, node):
            self.current = self.visit(node.value)
            self.generic_visit(node)

        def visit_ExprOrNew(self, node):
            # Handles expressions like (3) + 4 * 2
            self.current = self.visit(node.value)
            self.generic_visit(node)

        def visit_ExprStarmap(self, node):
            # Handles unpacking like 3, 4 * 2 but not required here
            self.generic_visit(node)

        def visit_Num(self, node):  # Redefine to handle Python 3.8+ Num
            self.stack.append(node.n)
            self.generic_visit(node)

        def evaluate_expression(self, node):
            self.stack.clear()
            self.current = 0
            self.visit(node)
            while self.stack:
                self.current = self.stack.pop()
            return self.current

    # Parse the expression safely using ast
    parsed = ast.parse(expr.replace(' ', ''))
    expr_body = parsed.body  # For Python 3.8+, it's body (not value for FunctionDef)
    if isinstance(expr_body, ast.Expression):  # For expressions like "3 + 4"
        node = expr_body.value
    else:  # If it's a statement (like in a function, but problem says it's an expr)
        # Assume it's a single expression as top-level
        node = expr_body
    return Evaluator().evaluate_expression(node)
