import re

def calc(expr: str) -> int:
    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isspace():
                i += 1
            elif s[i] in '+-*/^()':
                # Handle unary minus as a separate token
                if s[i] == '-' and (i == 0 or s[i-1].isspace() or s[i-1] in '+-*/^('):
                    # Look ahead to see if it's part of a negative number
                    j = i + 1
                    if j < n and (s[j].isdigit() or (s[j] == '-' and j + 1 < n and s[j+1].isdigit())):
                        # It's a unary minus followed by a number (possibly with sign)
                        num_start = i
                        if j + 1 < n and s[j+1] == '-':
                            j += 2
                        while j < n and s[j].isdigit():
                            j += 1
                        tokens.append('u-' + s[num_start:j])
                        i = j
                    else:
                        # Standalone unary minus
                        tokens.append('u-')
                        i += 1
                else:
                    tokens.append(s[i])
                    i += 1
            elif s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(s[i:j])
                i = j
            else:
                # Should not happen per problem constraints
                i += 1
        return tokens

    def precedence(op):
        if op in ('^',):
            return 3
        elif op in ('*', '/'):
            return 2
        elif op in ('+', 'u-'):
            return 1
        return 0

    def apply_op(ops, vals):
        op = ops.pop()
        b = vals.pop()
        a = vals.pop()
        if op == '+':
            vals.append(a + b)
        elif op == '-':
            vals.append(a - b)
        elif op == '*':
            vals.append(a * b)
        elif op == '/':
            # Truncate toward zero
            vals.append(int(a / b))
        elif op == '^':
            vals.append(a ** b)
        elif op.startswith('u-'):
            # Unary minus
            vals.append(-b)

    def evaluate(tokens):
        ops = []
        vals = []
        i = 0
        while i < len(tokens):
            t = tokens[i]
            if t == '(': 
                ops.append(t)
            elif t == ')':
                while ops and ops[-1] != '(': 
                    apply_op(ops, vals)
                ops.pop()  # remove '('
            elif t.startswith('u-'):
                # Unary minus
                val = -int(t[2:]) if len(t) > 2 else -1  # but problem says unary minus not on negative exponent
                vals.append(val)
            elif t.isdigit() or (t.startswith('-') and len(t) == 1):  # shouldn't happen per spec
                vals.append(int(t))
            elif t.isdigit():
                vals.append(int(t))
            else:
                # Binary operator
                while (ops and ops[-1] != '(' and precedence(ops[-1]) >= precedence(t)):
                    apply_op(ops, vals)
                ops.append(t)
            i += 1
        while ops:
            apply_op(ops, vals)
        return vals[0]

    tokens = tokenize(expr)
    return evaluate(tokens)
