def int_to_words(n: int) -> str:
    num_words = [
        '', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
        'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen',
        'seventeen', 'eighteen', 'nineteen'
    ]
    tens_words = [
        '', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'
    ]
    suffixes = ['', 'hundred', 'thousand', 'million']

    def convert_three(num):
        parts = []
        if num >= 100:
            parts.append(num_words[num // 100] + ' hundred')
            rem = num % 100
            if rem != 0:
                parts.append(convert_two(rem))
        elif 20 <= num < 100:
            parts.append(tens_words[num // 10])
            rem = num % 10
            if rem:
                parts.append(num_words[rem])
        elif 10 <= num < 20:
            parts.append(num_words[num])
        else:  # 0-9
            parts.append(num_words[num])
        return ' '.join(parts)

    def convert_two(num):
        if num == 0:
            return ''
        if num < 20:
            return num_words[num]
        tens = num // 10
        rem = num % 10
        res = tens_words[tens]
        if rem:
            res += '-' + num_words[rem]
        return res

    def decompose(num):
        parts = []
        i = 0
        while num > 0:
            chunk = num % 1000000
            num //= 1000000
            if i == 2:
                divisor = 1000  # thousand
            elif i == 1:
                divisor = 1    # just hundreds
            else:
                divisor = 1    # million's place, but only if needed
            # process the current chunk (up to 6 digits, but split into 3)
            # split into groups of 3 from the right
            # For 6 digits: millions, thousands, hundreds
            # For smaller: just hundreds/tens
            if chunk == 0:
                continue  # skip empty groups
            # split into 3-digit groups
            if chunk >= 1000:
                high = chunk // 1000
                mid = (chunk % 1000) // 100
                low = chunk % 100
                part = []
                if high != 0:
                    part.append(convert_three(high))
                    part.append('thousand')
                if mid != 0:
                    part.append(convert_three(mid))
                if low != 0:
                    part.append(convert_three(low))
                if part:
                    parts.append(' '.join(part).strip())
            else:
                # 1-3 digits
                part = convert_three(chunk)
                if part:
                    parts.append(part)
            i += 1
        # reverse the collected parts because we took modulus
        return ' '.join(reversed(parts))

    if n == 0:
        return 'zero'
    words = decompose(n)
    return words.strip()

