import re

def glob_match(name: str, pattern: str) -> bool:
    def parse_bracket(expr):
        if expr.startswith('[') and expr.endswith(']'):
            inside = expr[1:-1]
            if not inside:
                return (False, "empty")
            # Handle negation at start
            if inside.startswith('!'):
                neg = True
                content = inside[1:]
            else:
                neg = False
                content = inside
            if not content:
                return (neg, "empty")
            # Parse character classes or ranges
            parts = []
            i = 0
            n = len(content)
            while i < n:
                if content[i] == '-':
                    # Possible range
                    if i + 1 < n and content[i+1] != '^' and content[i+1] != ']' and content[i+1] != '-':
                        j = i + 2
                        if j < n and content[j] <= content[j+1]:
                            end = ord(content[j+1]) - ord('a') + 10  # 'a'='0', 'z'='25', 'A'='26', 'Z'='51'
                            if 'a' <= content[j] <= 'z':
                                start = ord(content[j]) - ord('a')
                                end_val = ord(content[j+1]) - ord('a') + 10
                                if start <= end_val:
                                    span = list(range(start, end_val + 1))
                                    # Convert to lowercase a-z and uppercase A-Z
                                    span_lower = [c for c in span if 'a' <= chr(c) <= 'z']
                                    span_upper = [c for c in span if 'A' <= chr(c) <= 'Z']
                                    parts.append(f"[{''.join(lower)}{''.join(upper)}]")
                                    i += len(str(end_val+1)) + 2  # skip the range
                                else:
                                    # Reverse if start > end (e.g., 'z-a')
                                    a = ord(content[j])
                                    b = ord(content[j+1])
                                    if b < a:
                                        rev = list(range(b+ord('a'), a+ord('a')+1))
                                        lower = [chr(c+32) for c in rev if 'a'<=chr(c)<='z']
                                        upper = [chr(c) for c in rev if 'A'<=chr(c)<='Z']
                                        parts.append(f"[{''.join(lower)}{''.join(upper)}]")
                                        i += len(str(a+1)) + 2
                                    else:
                                        parts.append(f"[{content[i]}")
                                        i += 1
                                # else invalid, treat as single char
                            else:
                                parts.append(f"[{content[i]}")
                                i += 1
                        else:
                            # invalid range, treat as literal '-'
                            parts.append("-")
                            i += 1
                    else:
                        # Single '-' character
                        parts.append("-")
                        i += 1
                elif content[i] == '^':
                    # Escape, treat as literal '^'
                    parts.append("^")
                    i += 1
                elif content[i] == '*':
                    parts.append(".*")
                    i += 1
                elif content[i] == '?':
                    parts.append(".")
                    i += 1
                elif content[i] == '[':
                    # Should not happen due to outer check
                    parts.append("[")
                    i += 1
                elif content[i] == ']':
                    parts.append("]")
                    i += 1
                else:
                    parts.append(content[i])
                    i += 1
            bracket_pattern = ''.join(parts)
            # Escape regex special chars except those handled by class
            # For safety, escape all except . * ? [ ] ^ - but handled above
            return (neg, f"(?:{bracket_pattern})")
        else:
            # Not a bracketed part
            return (False, pattern[i:])

    def compile_pattern(p):
        # Recursively parse the pattern into a regex
        def helper(s, idx):
            if idx >= len(s):
                return "", idx
            if s[idx] == '*':
                return ".*", idx + 1
            if s[idx] == '?':
                return ".", idx + 1
            if s[idx] == '[':
                neg, sub = parse_bracket(s[idx:])
                if neg:
                    return f"[^{sub}]", idx + 2 + len(sub) + 1  # skip to after ]
                else:
                    return f"[{sub}]", idx + 2 + len(sub) + 1
            # Normal character
            return s[idx], idx + 1
        regex, _ = helper(pattern, 0)
        # Ensure the entire pattern is consumed
        return re.compile(f"^{regex}$")

    try:
        return compile_pattern(pattern).fullmatch(name) is not None
    except re.error:
        # Invalid glob pattern, treat as not matching
        return False
