def parse_csv_line(line: str) -> list[str]:
    def parse_field(start: int) -> tuple[str, int]:
        in_quotes = False
        buffer = []
        i = start
        while i < len(line):
            c = line[i]
            if c == '"':
                if not in_quotes:
                    in_quotes = True
                else:
                    # Escaped quote: add a single quote to buffer
                    buffer.append('"')
                    in_quotes = False
                i += 1
            elif c == ',' and not in_quotes:
                # End of current field
                return ''.join(buffer), i
            else:
                if in_quotes:
                    buffer.append(c)
                i += 1
        # Reached end of line, finish field
        return ''.join(buffer), i

    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # Start of a quoted field
            start = i
            i += 1
            in_quotes = True
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        buffer.append('"')
                        i += 2
                    else:
                        in_quotes = False
                        i += 1
                else:
                    if in_quotes:
                        buffer.append(c)
                    i += 1
                if c == ',' and not in_quotes:
                    break
            fields.append(''.join(buffer))
        elif line[i] == ',':
            # Trailing comma or between unquoted fields
            fields.append('')
            i += 1
        else:
            # Unquoted field
            start = i
            while i < n and line[i] not in (',', '"'):
                i += 1
            fields.append(line[start:i])
    return fields
