def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, +, -, *, / and parentheses,
    with normal operator precedence. Division is integer division that truncates toward zero.
    """
    import re
    import operator

    def tokenize(s):
        tokens = re.findall(r'\d+|\S', s)
        return [int(t) if t.isdigit() else t for t in tokens]

    def shunting_yard(tokens):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        output = []
        stack = []
        for token in tokens:
            if token.isdigit():
                output.append(token)
            elif token in precedence:
                while stack and stack[-1] in precedence and precedence[stack[-1]] >= precedence[token]:
                    output.append(stack.pop())
                stack.append(token)
            else:
                raise ValueError("Invalid token: {}".format(token))
        while stack:
            output.append(stack.pop())
        return output

    def calculate(op, a, b):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b

    def calculate_expression(tokens):
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(token)
            else:
                b = stack.pop()
                a = stack.pop()
                stack.append(calculate(token, a, b))
        return int(stack[0])

    tokens = tokenize(expr)
    tokens = shunting_yard(tokens)
    return calculate_expression(tokens)
