def calc(expr: str) -> int:
    def apply_op(a, b, op):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b
        elif op == '^':
            return a ** b

    def parse_number(s):
        sign = 1
        if s[0] == '-':
            sign = -1
            s = s[1:]
        elif s[0] == '+':
            s = s[1:]
        i = 0
        while i < len(s) and s[i].isdigit():
            i += 1
        return sign * int(s[:i])

    def parse_expression(s):
        if s[0] == '(':
            i = 1
            while i < len(s) and s[i] != ')':
                i += 1
            return parse_expression(s[1:i]), s[i + 1:]
        else:
            return parse_number(s), s[1:]

    def parse_term(s):
        num, s = parse_expression(s)
        while s and s[0] in '+-*/':
            op = s[0]
            s = s[1:]
            if op == '+':
                num = apply_op(num, parse_expression(s)[0], '+')
            elif op == '-':
                num = apply_op(num, parse_expression(s)[0], '-')
            elif op == '*':
                num = apply_op(num, parse_expression(s)[0], '*')
            elif op == '/':
                num = apply_op(num, parse_expression(s)[0], '/')
            s = s[1:]
        return num, s

    def parse_factor(s):
        num, s = parse_term(s)
        while s and s[0] in '^':
            op = s[0]
            s = s[1:]
            num = apply_op(num, parse_term(s)[0], op)
            s = s[1:]
        return num, s

    def parse_primary(s):
        num, s = parse_factor(s)
        while s and s[0] == '(':
            _, s = parse_expression(s[1:])
            if s[0] != ')':
                raise ValueError("Mismatched parentheses")
            s = s[1:]
        return num, s

    def parse(s):
        num, s = parse_primary(s)
        while s:
            if s[0] in '+-*/':
                op = s[0]
                s = s[1:]
                num = apply_op(num, parse_primary(s)[0], op)
            elif s[0] == '^':
                op = s[0]
                s = s[1:]
                num = apply_op(num, parse_primary(s)[0], op)
            else:
                break
        return num, s

    return parse(expr)[0]
```

```python
def int_to_words(n: int) -> str:
    """
    Converts an integer to its English words representation.

    Args:
    n (int): The integer to convert.

    Returns:
    str: The English words representation of the integer.
    """
    if n == 0:
        return 'zero'

    def helper(num):
        ones = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine']
        teens = ['ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen']
        tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety']

        if num < 10:
            return ones[num]
        elif num < 20:
            return teens[num - 10]
        elif num < 100:
            return tens[num // 10] + ('-' + ones[num % 10] if num % 10 != 0 else '')
        elif num < 1000:
            return helper(num // 100) + ' hundred' + ('' if num % 100 == 0 else ' ' + helper(num % 100))
        elif num < 1000000:
            return helper(num // 1000) + ' thousand' + ('' if num % 1000 == 0 else ' ' + helper(num % 1000))
        else:
            return helper(num // 1000000) + ' million' + ('' if num % 1000000 == 0 else ' ' + helper(num % 1000000))

    return ' '.join(helper(n).split())
```

