def flatten_json(obj: dict) -> dict:
    def _flatten(obj, path=""):
        if isinstance(obj, dict):
            for key, value in obj.items():
                new_path = f"{path}.{key}" if path else key
                if isinstance(value, (dict, list)):
                    yield from _flatten(value, new_path)
                else:
                    yield {new_path: value}
        elif isinstance(obj, list):
            for i, value in enumerate(obj):
                new_path = f"{path}.{i}" if path else str(i)
                if isinstance(value, (dict, list)):
                    yield from _flatten(value, new_path)
                else:
                    yield {new_path: value}
        else:
            yield {path: obj}

    return dict(_flatten(obj))
```

```python
def parse_csv_line(line: str) -> list[str]:
    """
    Split a CSV line into fields. Fields are separated by commas.
    A field may be wrapped in double quotes; inside a quoted field,
    commas are literal and two double quotes "" stand for one double quote.
    Unquoted fields are taken as-is (no trimming).
    An empty line is one empty field, and a trailing comma means a final empty field.
    """
    fields = []
    current_field = []
    in_quotes = False
    escaped_quotes = False

    for char in line:
        if char == '"':
            if in_quotes:
                if escaped_quotes:
                    current_field.append(char)
                    escaped_quotes = False
                else:
                    in_quotes = not in_quotes
                    escaped_quotes = True
            else:
                in_quotes = True
        elif char == ',':
            if not in_quotes:
                fields.append(''.join(current_field))
                current_field = []
        else:
            if in_quotes:
                if escaped_quotes:
                    current_field.append(char)
                    escaped_quotes = False
                else:
                    current_field.append(char)
            else:
                current_field.append(char)
    if current_field:
        fields.append(''.join(current_field))
    if line.strip() == '':
        fields.append('')
    return fields
